using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;

static class Program {
 static string root=FindRoot(),output=Path.Combine(root,"analysis/full-audit/read-calib-file/checks");static int checks;
 static string FindRoot(){var p=new DirectoryInfo(AppContext.BaseDirectory);while(p is not null&&!File.Exists(Path.Combine(p.FullName,"docs/PARALLEL-WORK.md")))p=p.Parent;return p!.FullName;}
 static void Check(bool value,string message){checks++;if(!value)throw new InvalidOperationException(message);}
 static Dictionary<string,JsonElement> Defaults(ReadCalibFilePlugin p)=>p.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());
 static NodeDocument Node(string id,Dictionary<string,JsonElement> v)=>new(id,ReadCalibFilePlugin.Id,"1.0.0","标定加载",v);
 static ToolEditorContext Editor(ReadCalibFilePlugin p,string id,Dictionary<string,JsonElement> v,ModuleExecutionScope scope)=>new(Node(id,v),root,_=>{},_=>throw new NotSupportedException()){Scope=scope};
 static ModuleResult Run(ReadCalibFilePlugin p,string id,Dictionary<string,JsonElement> v,ModuleExecutionScope scope,IReadOnlyDictionary<string,PortValue>? inputs=null)=>p.CreateRuntime().ExecuteAsync(new(id,root,inputs??new Dictionary<string,PortValue>(),v){Scope=scope},CancellationToken.None).Result;
 [STAThread] static int Main(){try{Directory.CreateDirectory(output);Replay();Basic();Console.WriteLine($"ReadCalibFile.PluginChecks: {checks} checks passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Replay(){using var evidence=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"docs/plugins/read-calib-file-evidence.json")));var fixtures=evidence.RootElement.GetProperty("fixtures").EnumerateArray().ToDictionary(f=>f.GetProperty("name").GetString()!,f=>f.GetProperty("xml").GetString()!);var plugin=new ReadCalibFilePlugin();using var scope=new ModuleExecutionScope();var values=Defaults(plugin);string id="";ReadCalibFileData data=new();int scenarios=0;
  foreach(var row in evidence.RootElement.GetProperty("events").EnumerateArray()){
   string phase=row.GetProperty("phase").GetString()!;
   if(phase=="instance-start"){id="native-"+row.GetProperty("serial").GetInt32();values=Defaults(plugin);data=new();}
   if(phase=="load"){
    string file=Path.GetFileName(row.GetProperty("path").GetString()!);string local=Path.Combine(output,id+"-"+file);if(row.TryGetProperty("xml",out var xmlValue)&&xmlValue.GetString() is {Length:>0} originalXml)File.WriteAllText(local,originalXml);else if(fixtures.TryGetValue(file,out var xml))File.WriteAllText(local,xml);
    var result=plugin.Load(Editor(plugin,id,values,scope),local);Check(result.ErrorCode==row.GetProperty("code").GetUInt32(),id+" load "+file);values["FilePath"]=JsonSerializer.SerializeToElement(local);if(result.ReplaceData&&result.Data is {} parsed)data=parsed;values["OutputSchema"]=JsonSerializer.SerializeToElement(ReadCalibFilePlugin.Schema(data));
   }
   if(phase=="replace-file"){File.WriteAllText(Path.Combine(output,id+"-"+row.GetProperty("target").GetString()),fixtures[row.GetProperty("source").GetString()!]);}
   if(phase=="delete-file")File.Delete(Path.Combine(output,id+"-"+row.GetProperty("target").GetString()));
   if(phase=="load-cache"){data=ReadCalibFileData.Parse(fixtures["rich.xml"]).Data!;values["FilePath"]=JsonSerializer.SerializeToElement("");values["CachedFileData"]=JsonSerializer.SerializeToElement(fixtures["rich.xml"]);values["OutputSchema"]=JsonSerializer.SerializeToElement(ReadCalibFilePlugin.Schema(data));}
   if(phase=="set"){string key=row.GetProperty("key").GetString()!,text=row.GetProperty("value").GetString()!;if(key=="FilePath"){plugin.Load(Editor(plugin,id,values,scope),text);values[key]=JsonSerializer.SerializeToElement(text);if(text.Length==0)data=new();}else if(key=="SaveCalibDataEnable")values[key]=JsonSerializer.SerializeToElement(text=="True");else if(key is "DynamicInData" or "DynamicOutData")values[key]=JsonSerializer.SerializeToElement(text);}
   if(phase=="get"&&row.GetProperty("key").GetString()=="GetCalibInputParam")Check(data.InputDescription()==row.GetProperty("value").GetString(),id+" input description");
   if(phase!="run")continue;scenarios++;string label=row.GetProperty("label").GetString()!;var input=row.GetProperty("inputs").EnumerateObject().ToDictionary(p=>p.Name,p=>p.Name=="RefreshSignal"?PortValue.Integer(p.Value[0].GetInt64()):p.Value.GetArrayLength()!=1?PortValue.Numbers(p.Value.EnumerateArray().Select(v=>v.GetDouble())):PortValue.Number(p.Value[0].GetDouble()));if(row.TryGetProperty("strings",out var textInputs))foreach(var text in textInputs.EnumerateObject())input[text.Name]=PortValue.Text(text.Value.GetString()!);var actual=Run(plugin,id,values,scope,input);Check(actual.Status==ModuleStatus.Success,label+" status");
   var expected=new Dictionary<string,(string Type,SortedDictionary<int,double> Values,string? Text)>();foreach(var w in row.GetProperty("writes").EnumerateArray()){string name=w.GetProperty("name").GetString()!,type=w.GetProperty("type").GetString()!;if(type=="string"){expected[name]=(type,new(),w.GetProperty("text").GetString());continue;}if(!expected.TryGetValue(name,out var item))item=(type,new(),null);int index=w.TryGetProperty("index",out var idx)?idx.GetInt32():0;foreach(var number in w.GetProperty("values").EnumerateArray())item.Values[index++]=number.GetDouble();expected[name]=item;}
   Check(actual.Outputs.Keys.Where(n=>n is not("ModuRunTime" or "CalibData")).ToHashSet().SetEquals(expected.Keys),label+" exact output presence");
   foreach(var item in expected){Check(actual.Outputs.ContainsKey(item.Key),label+" output "+item.Key);var value=actual.Outputs[item.Key];if(item.Value.Type=="string"){Check(value.Kind==DataKind.Text&&value.As<string>()==item.Value.Text,label+" text "+item.Key);continue;}var numbers=value.Kind==DataKind.Integer?new[]{(double)value.As<long>()}:value.Kind==DataKind.Number?new[]{value.As<double>()}:value.As<IReadOnlyList<double>>().ToArray();Check(numbers.Length==item.Value.Values.Count,label+" count "+item.Key);int i=0;foreach(double expectedValue in item.Value.Values.Values)Check(item.Value.Type=="int"?numbers[i++]==expectedValue:BitConverter.SingleToInt32Bits((float)numbers[i++])==BitConverter.SingleToInt32Bits((float)expectedValue),label+" exact float32/int value "+item.Key);}
  }Check(scenarios>=22,"Original process replay scenario count");
 }
 sealed class IntegerSource:IModule {public ModuleDescriptor Descriptor{get;}=new("test.read-int","1","source",[],new[]{new PortDescriptor("Value",DataKind.Integer)},[]);public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"Value",PortValue.Integer(123456789)}}));}
 static void Basic(){var plugin=new ReadCalibFilePlugin();var values=Defaults(plugin);using var scope=new ModuleExecutionScope();Check(plugin.LastDisplay(Node("not-run",values),root,scope) is null,"Display has no snapshot before execution");Check(values["SaveCalibDataEnable"].GetBoolean(),"Original save-cache default");Check(plugin.Descriptor.Inputs.Count==10,"Original ten inputs");Check(Run(plugin,"empty",values,scope).Outputs["ModuStatus"].As<long>()==0,"No file is successful NG status");
  string xml="<Root><CalibInputParam/><CalibOutputParam><P ParamName='Dynamic' DataType='float'><V>42</V></P></CalibOutputParam></Root>";string path=Path.Combine(output,"persistent.xml");File.WriteAllText(path,xml);values["FilePath"]=JsonSerializer.SerializeToElement(path);var data=ReadCalibFileData.Parse(xml).Data!;values["OutputSchema"]=JsonSerializer.SerializeToElement(ReadCalibFilePlugin.Schema(data));Check(plugin.DescribeNode(Node("persist",values)).Outputs.Any(p=>p.Name=="Dynamic"&&p.Kind==DataKind.Number),"Persisted dynamic descriptor");Check(Run(plugin,"persist",values,scope).Outputs["Dynamic"].As<double>()==42,"Custom output runs");var frame=plugin.LastDisplay(Node("persist",values),root,scope)!;Check(frame.RecordText=="Module Status:1"&&frame.RecordVisible&&!frame.TextVisible&&!frame.ImageVisible&&!frame.ResultListVisible,"Only original Data Record is active");var saved=plugin.PrepareSave(Node("persist",values),root,new ResourceCatalog(root,[]),scope);Check(saved.Node.Parameters["CachedFileData"].GetString()==xml,"Save enabled embeds file content");File.Delete(path);Check(plugin.LastDisplay(Node("persist",values),root,scope)!.RecordText=="Module Status:1","Display uses captured snapshot after file removal");var fresh=new ReadCalibFilePlugin();using var other=new ModuleExecutionScope();Check(Run(fresh,"cached",saved.Node.Parameters,other).Outputs["Dynamic"].As<double>()==42,"Cached calibration survives missing source");
  values["SaveCalibDataEnable"]=JsonSerializer.SerializeToElement(false);var noCache=plugin.PrepareSave(Node("persist",values),root,new ResourceCatalog(root,[]),scope);Check(noCache.Node.Parameters["CachedFileData"].GetString()=="","Save disabled omits cached data");Check(Run(new ReadCalibFilePlugin(),"no-cache",noCache.Node.Parameters,other).Outputs["ModuStatus"].As<long>()==0,"Disabled cache uses missing disk state");
  File.WriteAllText(path,xml);values["SaveCalibDataEnable"]=JsonSerializer.SerializeToElement(true);var first=Run(plugin,"refresh",values,scope);Check(first.Outputs.ContainsKey("Dynamic"),"Refresh initial schema");File.WriteAllText(path,xml.Replace("Dynamic","Changed"));Check(Run(plugin,"refresh",values,scope).Outputs.ContainsKey("Dynamic"),"Disk change alone does not reload");var refresh=new Dictionary<string,PortValue>{{"RefreshSignal",PortValue.Integer(1)}};Check(Run(plugin,"refresh",values,scope,refresh).ErrorCode=="CALIBRATION_SCHEMA_CHANGED","Refresh schema change is explicit boundary");values["OutputSchema"]=JsonSerializer.SerializeToElement(ReadCalibFilePlugin.Schema(ReadCalibFileData.Read(path).Data!));Check(Run(plugin,"refresh",values,scope).Outputs["Changed"].As<double>()==42,"Confirmed updated schema runs");File.Delete(path);Check(Run(plugin,"refresh",values,scope,refresh).Outputs["Changed"].As<double>()==42,"Failed refresh retains preceding parsed results");
  string sentinel="<R><CalibInputParam/><CalibOutputParam><P ParamName='P' DataType='CalibPointF'><X>-9999</X><Y>-9999</Y><R>-990.001</R></P></CalibOutputParam></R>";var sentinelValues=ReadCalibFileData.Parse(sentinel).Data!.Values();Check(sentinelValues.Count==2&&!sentinelValues.ContainsKey("R"),"Only angle uses native -990 sentinel threshold");Check(ReadCalibFileData.Parse("<R><CalibInputParam/></R>").ErrorCode==0xe0000017,"Missing output section native error");Check(ReadCalibFileData.Parse("broken").ReplaceData==false,"Malformed XML preserves previous data");
  var registry=new ModuleRegistry();registry.Register(plugin.Descriptor,plugin.CreateRuntime,plugin.DescribeNode);foreach(var bad in new[]{JsonSerializer.SerializeToElement("{"),JsonSerializer.SerializeToElement(123),JsonSerializer.SerializeToElement("[{\"Name\":\"X\",\"Kind\":999}]"),JsonSerializer.SerializeToElement("[null]")}){var broken=Defaults(plugin);broken["OutputSchema"]=bad;var validation=GraphValidator.Validate(new ProcedureDocument("bad","bad",new[]{Node("bad",broken)},[]),registry);Check(!validation.IsValid&&validation.Issues.Any(i=>i.Code=="Module"),"Malformed persisted schema is a graph validation issue");}
  var extraOutput=new Dictionary<string,PortValue>();new ReadCalibFileExtra("F","float",false).Copy(new Dictionary<string,PortValue>{{"F",PortValue.Integer(123)}},extraOutput);Check(extraOutput["F"].Kind==DataKind.Number&&extraOutput["F"].As<double>()==123,"Extra float getter integer fallback");new ReadCalibFileExtra("F","float",false).Copy(new Dictionary<string,PortValue>{{"F",PortValue.Numbers([])}},extraOutput);Check(extraOutput["F"].As<double>()==123,"Successful empty numeric input makes no extra write");new ReadCalibFileExtra("ModuStatus","int",false).Copy(new Dictionary<string,PortValue>{{"ModuStatus",PortValue.Integer(9)}},extraOutput);Check(extraOutput["ModuStatus"].As<long>()==9,"Extra result overwrites matching integer output");foreach(var bad in new[]{JsonSerializer.SerializeToElement("<broken"),JsonSerializer.SerializeToElement(42)}){var broken=Defaults(plugin);broken["DynamicOutData"]=bad;Check(!GraphValidator.Validate(new ProcedureDocument("bad-extra","bad",new[]{Node("bad-extra",broken)},[]),registry).IsValid,"Malformed extra XML is a graph validation issue");}
  registry.Register(new IntegerSource().Descriptor,()=>new IntegerSource());foreach(bool array in new[]{false,true}){var dynamicValues=Defaults(plugin);dynamicValues["DynamicOutData"]=JsonSerializer.SerializeToElement("<ParamRoot><Categorys><Category Name='Output'><Items><Filter Name='DisplayFloat' ValueType='float' IsArray='"+array.ToString()+"' Others='IsResultShow=true'/></Items></Category></Categorys></ParamRoot>");var read=Node("read-fallback-"+array,dynamicValues);var source=new NodeDocument("integer","test.read-int","1","source",[]);var procedure=new ProcedureDocument("read-integer-"+array,"integer",new[]{source,read},new[]{new ConnectionDocument(source.Id,"Value",read.Id,"DisplayFloat")});Check(GraphValidator.Validate(procedure,registry).IsValid,"Dynamic float accepts integer graph source");var execution=new GraphExecutor(registry).RunAsync(procedure,root,scope:scope).Result;Check(execution.Status==SessionStatus.Success,"Dynamic integer fallback executes in graph");var result=execution.Nodes.Single(n=>n.NodeId==read.Id);Check(array?result.Outputs["DisplayFloat"].As<IReadOnlyList<double>>()[0]==(float)123456789:result.Outputs["DisplayFloat"].As<double>()==(float)123456789,"Graph preserves original float cast");}
  if(System.Windows.Application.Current is null)new System.Windows.Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var ui=Defaults(plugin);var window=new ReadCalibFileWindow(Editor(plugin,"ui",ui,scope),plugin){Left=-30000,Top=-30000,ShowActivated=false,ShowInTaskbar=false};window.Show();window.UpdateLayout();Check(window.Title=="标定加载"&&window.ActualHeight>500,"Dedicated WPF editor renders");var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(output,"independent-default.png")))encoder.Save(file);window.Close();
  using(var fixture=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"docs/plugins/read-calib-file-evidence.json")))){string rich=fixture.RootElement.GetProperty("fixtures").EnumerateArray().Single(f=>f.GetProperty("name").GetString()=="rich.xml").GetProperty("xml").GetString()!;string loadedPath=Path.Combine(output,"acceptance.xml");File.WriteAllText(loadedPath,rich);var loadedValues=Defaults(plugin);loadedValues["FilePath"]=JsonSerializer.SerializeToElement(loadedPath);loadedValues["OutputSchema"]=JsonSerializer.SerializeToElement(ReadCalibFilePlugin.Schema(ReadCalibFileData.Parse(rich).Data!));Dictionary<string,JsonElement>? applied=null;var loadedContext=Editor(plugin,"ui-loaded",loadedValues,scope) with{Apply=v=>applied=v};var loadedWindow=new ReadCalibFileWindow(loadedContext,plugin){Left=-30000,Top=-30000,ShowActivated=false,ShowInTaskbar=false};loadedWindow.Show();loadedWindow.UpdateLayout();Check(Visuals(loadedWindow).OfType<System.Windows.Controls.TextBox>().Count(t=>t.IsReadOnly)==72,"Two original twelve-point lists render exactly three read-only columns");Check(Visuals(loadedWindow).OfType<System.Windows.Controls.TextBlock>().Any(t=>t.Text=="物理点"),"Original localized point-list label");var toggle=Visuals(loadedWindow).OfType<System.Windows.Controls.Primitives.ToggleButton>().Single(t=>t.Name=="SaveCalibDataEnable");toggle.IsChecked=false;toggle.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(applied is not null&&!applied["SaveCalibDataEnable"].GetBoolean(),"Source-confirmed switch immediately applies save setting");Visuals(loadedWindow).OfType<System.Windows.Controls.ScrollViewer>().First().ScrollToBottom();loadedWindow.UpdateLayout();var loadedBitmap=new RenderTargetBitmap((int)loadedWindow.ActualWidth,(int)loadedWindow.ActualHeight,96,96,PixelFormats.Pbgra32);loadedBitmap.Render(loadedWindow);var loadedEncoder=new PngBitmapEncoder();loadedEncoder.Frames.Add(BitmapFrame.Create(loadedBitmap));using(var file=File.Create(Path.Combine(output,"independent-loaded-points.png")))loadedEncoder.Save(file);loadedWindow.Close();}
 }
 static IEnumerable<DependencyObject> Visuals(DependencyObject value){yield return value;for(int i=0;i<VisualTreeHelper.GetChildrenCount(value);i++)foreach(var child in Visuals(VisualTreeHelper.GetChild(value,i)))yield return child;}
}
